import View from "../../core/View";
import Helper from "../../supports/Helper";
import SelectInput from "../Inputs/SelectInput";

export default class TemplateSelection extends View {
    _defineProps() {
        return {
            paginator: {},
            categories: [],
            prices: [],
            query: {
                category_id: "",
                search: "",
                sort: "latest",
            },
        };
    }

    _defineState() {
        return {
            ...this._props,
        };
    }

    _template() {
        const { paginator, query } = this._state;
        const { data } = paginator;


        return `
            <div>
                <form id="search-form" class="no-page-search-form">
                    <div class="no-page-search-form__actions">
                        <button type="button" class="no-btn-success --xs" id="btn-reset">
                            초기화
                        </button>
                        <button type="submit" class="no-btn-primary --xs" id="btn-submit">
                            검색
                        </button>
                    </div>

                    <div class="no-page-search-form-row">
                        <div data-ref="category"></div>

                        <div class="no-form-search">
                            <label for="query" class="no-form-label">검색</label>
                            <div class="no-form-search-inner">
                                <div class="no-form-search__icon">
                                    <i class="fa-light fa-magnifying-glass"></i>
                                </div>
                                <input 
                                    type="search" 
                                    name="search" 
                                    id="query" 
                                    class="no-form-search-input" 
                                    placeholder="제품명, 모델명, 코드, 설명" 
                                    value="${query.search || ""}"
                                />
                            </div>
                        </div>
                        
                        <div data-ref="sort"></div>
                    </div>
                </form>
            
                <div class="no-page-index-table-outer">
                    <table class="no-page-index-table">
                        <thead>
                            <tr>
                                <th>이미지</th>
                                <th>제품명</th>
                                <th>모델명</th>
                                <th>코드</th>
                                <th>단가(USD)</th>
                                <th>관리</th>
                            </tr>
                        </thead>
                        <tbody>
                            ${data.map(this._renderItem).join("")}
                        </tbody>
                    </table>
                </div>

                ${this._renderPagination(paginator)}
            </div>
        `;
    }

    _render() {
        super._render();
        
        
        this.form = this.qs("#search-form");
        console.log(this.form);

        SelectInput.make(this.refs.sort, {
            label: "정렬",
            name: "sort",
            value: this._state.query.sort || "",
            options: [
                { label: "최신순", value: "latest" },
                { label: "오래된순", value: "oldest" },
            ],
        }).render();

        const options =
            this.state.categories.length > 1
                ? [{ label: "전체", value: "" }]
                : [];

        SelectInput.make(this.refs.category, {
            label: "제품군 선택",
            name: "category_id",
            value: this._state.query.category_id || "",
            options: [
                ...options,
                ...this._state.categories.map((c) => ({
                    label: c.label,
                    value: c.id,
                })),
            ],
        }).render();
    }

    _renderPagination(paginator) {
        const {
            from = 0,
            to = 0,
            total = 0,
            has_previous_page = false,
            has_next_page = false,
            current_page = 1,
            per_page = 15,
        } = paginator;

        return `
            <div class="no-pagination">
                <p class="no-pagination__text">Rows per page:</p>
                <div class="no-pagination__input">
                    <select name="perpage" class="no-pagination__select">
                        ${[15, 25, 50, 75, 100]
                            .map(
                                (v) => `
                            <option value="${v}" ${
                                    v == per_page ? "selected" : ""
                                }>${v}</option>
                        `
                            )
                            .join("")}
                    </select>
                </div>
                <div class="no-pagination__text">
                    ${from}-${to} of ${total}
                </div>
                <div class="no-pagination__btn">
                    <button type="button" class="no-btn-move ${
                        !has_previous_page ? "--disabled" : ""
                    }" data-move="prev">
                        <i class="fa-duotone fa-light fa-chevron-left"></i>
                    </button>
                    <button type="button" class="no-btn-move ${
                        !has_next_page ? "--disabled" : ""
                    }" data-move="next">
                        <i class="fa-duotone fa-light fa-chevron-right"></i>
                    </button>
                </div>
            </div>
        `;
    }

    _renderItem({ id, fileattachment, name, model, code, price } = {}) {
        const mainImage = fileattachment.find(
            (file) => file.file_key === "main_image"
        );

        return `
            <tr>
                <td>
                    ${
                        mainImage
                            ? `
                        <div class="no-page-index-table__thumb">
                            <img width="80" src="${
                                mainImage.upload_path
                            }" alt="${model || name}"/>
                        </div>
                    `
                            : `-`
                    }
                </td>
                <td><span>${name}</span></td>
                <td><span>${model || "-"}</span></td>
                <td><span>${code || "-"}</span></td>
                <td><span>${price || "-"}</span></td>
                <td>
                    <div class="no-prod-attr-list__action">
                        <button 
                            type="button" 
                            class="no-btn-primary-outline" 
                            data-row-id="${id}">
                            <span>선택</span>
                        </button>
                    </div>
                </td>
            </tr>
        `;
    }

    _bindEvents() {
        const buttons = this.qsAll("button[data-row-id]");
        buttons.forEach((btn) => {
            this.on(btn, "click", this._handleClick.bind(this));
        });
        
        if (this.form) {
            this.on(this.form, "submit", (e) => {
                e.preventDefault();
                this._handleSearch(this.form, e);
            });
        }

        const moveButtons = this.qsAll(".no-btn-move");
        moveButtons.forEach((btn) => {
            this.on(btn, "click", this._handleMove.bind(this));
        });

        const perPageSelect = this.qs(".no-pagination__select");
        if (perPageSelect) {
            this.on(perPageSelect, "change", this._handlePerPage.bind(this));
        }

        const resetButton = this.qs("#btn-reset");
        if (resetButton) {
            this.on(resetButton, "click", this._handleReset.bind(this));
        }

        const submitBtn = this.qs("#btn-submit");
        if (submitBtn) {
            this.on(submitBtn, "click", this._handleSearch.bind(this));
        }
    }

    _handleReset() {
        const params = new URLSearchParams({
            perpage: this._state.paginator.per_page || 15,
            page: 1,
            category_id: "",
            search: "",
            sort: "latest",
        });

        this._dispatch("fetch.templates", {
            query: params.toString(),
        });
    }

    _handleSearch(form, evt) {
        if (evt) evt.preventDefault();

        const formData = new FormData(this.form);
        const params = new URLSearchParams();

        for (const [key, value] of formData.entries()) {
            if (value) {
                params.append(key, value);
            }
        }

        this._dispatch("fetch.templates", {
            query: params.toString(),
        });
    }

    // 교체용
    _handleMove(form, evt) {
        evt.preventDefault();

        const button = evt.currentTarget;
        if (button.classList.contains("--disabled")) return;

        const move = button.getAttribute("data-move"); // 'prev' | 'next'
        let page = Number(this._state.paginator?.current_page || 1);

        if (move === "prev") page = Math.max(1, page - 1);
        if (move === "next") page += 1;

        const params = new URLSearchParams();

        // 현재 검색 조건 유지
        const q = this._state.query || {};
        if (q.search) params.set("search", q.search);
        if (q.category_id) params.set("category_id", q.category_id);
        if (q.sort) params.set("sort", q.sort);

        // perpage는 선택 값(없으면 paginator의 per_page) 유지
        const perSelect = this.qs(".no-pagination__select");
        const perpage =
            (perSelect && perSelect.value) ||
            this._state.paginator?.per_page ||
            15;
        params.set("perpage", String(perpage));

        // 이동할 페이지
        params.set("page", String(page));

        this._dispatch("fetch.templates", {
            query: params.toString(),
        });
    }

    _handlePerPage(select, evt) {
        const perpage = evt.currentTarget.value;

        const params = new URLSearchParams();
        const q = this._state.query || {};

        if (q.search) params.set("search", q.search);
        if (q.category_id) params.set("category_id", q.category_id);
        if (q.sort) params.set("sort", q.sort);

        params.set("perpage", perpage);
        params.set("page", "1");

        this._dispatch("fetch.templates", {
            query: params.toString(),
        });
    }

    _handleClick(form, evt) {
        const id = evt.currentTarget.getAttribute("data-row-id");
        const template = this._state.paginator.data.find(
            (item) => item.id === +id
        );

        // 제품별 단가별 금액 변경
        const dealerPrice = this._state.prices.find(
            (price) => price.product_template_id === template.id
        );

        if (dealerPrice) {
            console.log(
                `단가 변경됨. 기존: ${template.price} -> 대리점: ${dealerPrice.price}`
            );
            template.price = dealerPrice.price;
        }

        this._dispatch("pick.template", { template });
    }
}
